1	// src/lib/plattform/dealroom.js
2	//
3	// Stammlisten und reine Regeln des Deal-Rooms (Q&A, Bieterverfahren, Datenraum 2.0,
4	// Investor-Pipeline, Anbieter-Cockpit). Client- und serverseitig nutzbar – keine Node-Importe.
5	// Frappe spiegelt die Tabellen in `plattform/dealroom_regeln.py` (identisch halten).
6	//
7	// Grundsatz Umgehungsschutz: Anbieter und Investoren sehen sich gegenseitig NICHT, bis das
8	// Backoffice die Kontakte je Interesse freigibt („Kontaktfreigabe“). Bis dahin erscheinen
9	// Investoren beim Anbieter nur als Pseudonym („Investor A“), der Anbieter beim Investor nur
10	// als „Anbieter“. Freitexte (Fragen, Antworten, Gebotsbedingungen) werden zusätzlich von
11	// E-Mail-Adressen, Telefonnummern und Links bereinigt.
12	
13	import { DATENRAUM_STATUS } from "./prozesse";
14	
15	// ---------------------------------------------------------------- Q&A
16	
17	export const QA_KATEGORIEN = {
18	  technisch: "Technisch",
19	  rechtlich: "Rechtlich",
20	  kaufmaennisch: "Kaufmännisch",
21	  netz: "Netz",
22	};
23	export const QA_KATEGORIE_IDS = Object.keys(QA_KATEGORIEN);
24	
25	/**
26	 * Status einer Frage (intern). Für Investoren zählt nur offen/beantwortet (`qaOeffentlicherStatus`).
27	 *   eingereicht     – Investor hat gefragt, Moderation durch ÖkoInvest ausstehend
28	 *   freigegeben     – anonymisiert an den Anbieter weitergegeben, Antwortfrist läuft
29	 *   beantwortet     – Anbieter hat geantwortet, Freigabe der Antwort durch ÖkoInvest ausstehend
30	 *   veroeffentlicht – Antwort freigegeben (für den Fragenden, optional für alle NDA-Investoren)
31	 *   abgelehnt       – nicht zugelassen (z. B. Umgehungsversuch, Dublette)
32	 */
33	export const FRAGE_STATUS = {
34	  eingereicht: { label: "In Moderation", ton: "warn" },
35	  freigegeben: { label: "Offen beim Anbieter", ton: "info" },
36	  beantwortet: { label: "Antwort in Prüfung", ton: "warn" },
37	  veroeffentlicht: { label: "Beantwortet", ton: "ok" },
38	  abgelehnt: { label: "Nicht zugelassen", ton: "neutral" },
39	};
40	export const qaOeffentlicherStatus = (s) => (s === "veroeffentlicht" ? "beantwortet" : s === "abgelehnt" ? "abgelehnt" : "offen");
41	export const QA_FRIST_TAGE = { standard: 5, min: 1, max: 30 };
42	
43	// ---------------------------------------------------------------- Datenraum 2.0
44	
45	/** Standard-Index des Datenraums (Reihenfolge = Nummerierung) */
46	export const DATENRAUM_ORDNER = [
47	  { id: "flaeche", nr: "01", label: "Fläche & Sicherung", text: "Lageplan, Grundbuch, Pacht- und Nutzungsverträge" },
48	  { id: "planung", nr: "02", label: "Planung & Genehmigung", text: "Aufstellungs-/Satzungsbeschluss, Widmung, Baugenehmigung, Gutachten" },
49	  { id: "netz", nr: "03", label: "Netz", text: "Netzanfrage, Netzanschlusszusage, Reservierung, Trassenplanung" },
50	  { id: "technik", nr: "04", label: "Technik", text: "Anlagenlayout, Komponenten, Betriebsdaten, Wartung" },
51	  { id: "ertrag", nr: "05", label: "Ertrag", text: "Ertragsgutachten (P50/P90), Verschattung, Messdaten" },
52	  { id: "vertraege", nr: "06", label: "Verträge", text: "EEG-/EAG-Zuschlag, PPA, Direktvermarktung, Dienstleister" },
53	  { id: "finanzen", nr: "07", label: "Finanzen", text: "Finanzmodell, Kostenschätzung, Steuern, Förderungen" },
54	  { id: "allgemein", nr: "00", label: "Allgemein", text: "Exposé, Steckbrief, Sonstiges" },
55	];
56	export const DATENRAUM_ORDNER_IDS = DATENRAUM_ORDNER.map((o) => o.id);
57	export const ordnerLabel = (id) => DATENRAUM_ORDNER.find((o) => o.id === id)?.label || "Allgemein";
58	
59	/** Ordner aus dem Checklisten-Schlüssel eines Dokuments (Vorbelegung) */
60	export const ORDNER_FUER_CHECKLISTE = {
61	  pacht: "flaeche",
62	  lageplan: "flaeche",
63	  netzzusage: "netz",
64	  aufstellung: "planung",
65	  gutachten: "planung",
66	  satzung: "planung",
67	  baugenehmigung: "planung",
68	  ertrag: "ertrag",
69	  eeg: "vertraege",
70	  betrieb: "technik",
71	};
72	
73	export function ordnerVorschlag(dokument) {
74	  if (ORDNER_FUER_CHECKLISTE[dokument?.checkliste]) return ORDNER_FUER_CHECKLISTE[dokument.checkliste];
75	  const n = String(dokument?.name || "").toLowerCase();
76	  if (/netz|einspeis|umspann/.test(n)) return "netz";
77	  if (/ertrag|p50|p90|yield/.test(n)) return "ertrag";
78	  if (/finanz|kosten|capex|modell|steuer/.test(n)) return "finanzen";
79	  if (/vertrag|ppa|eeg|eag|zuschlag|direktvermarkt/.test(n)) return "vertraege";
80	  if (/beschluss|satzung|genehmig|bewilligung|widmung|gutacht|b-plan|bebauungsplan/.test(n)) return "planung";
81	  if (/lageplan|grundbuch|flur|pacht|nutzungsvertr/.test(n)) return "flaeche";
82	  if (/layout|modul|wechselricht|technik|betrieb|wartung/.test(n)) return "technik";
83	  return "allgemein";
84	}
85	
86	/**
87	 * Freigabestufen. Stufe 1: nach NDA-Freigabe (Datenraum frei). Stufe 2: nach LOI bzw. als
88	 * zugelassener Teilnehmer der verbindlichen Runde eines Bieterverfahrens.
89	 */
90	export const DATENRAUM_STUFEN = {
91	  1: { label: "Stufe 1", text: "nach NDA-Freigabe" },
92	  2: { label: "Stufe 2", text: "nach LOI bzw. Zulassung zur verbindlichen Runde" },
93	};
94	export const STUFE2_STATUS = ["loi_abgegeben", "loi_angenommen", "abgeschlossen"];
95	
96	/** Höchste Stufe eines Investors (0 = kein Datenraum) */
97	export function investorStufe(interesse, { verbindlichZugelassen = false } = {}) {
98	  if (!interesse || !DATENRAUM_STATUS.includes(interesse.status)) return 0;
99	  if (STUFE2_STATUS.includes(interesse.status) || verbindlichZugelassen) return 2;
100	  return 1;
101	}
102	
103	/** Download-Dateiname mit „Wasserzeichen“ (Empfänger + Datum) – ASCII-sicher, Endung bleibt */
104	export function wasserzeichenName(name, empfaenger, am = new Date()) {
105	  const s = String(name || "dokument.pdf");
106	  const punkt = s.lastIndexOf(".");
107	  const basis = (punkt > 0 ? s.slice(0, punkt) : s).trim();
108	  const endung = punkt > 0 ? s.slice(punkt) : "";
109	  const wer = [empfaenger?.vorname, empfaenger?.nachname].filter(Boolean).join(" ").replace(/\s*\(demo\)\s*/i, " Demo").trim() || "Empfaenger";
110	  const tag = new Date(am).toLocaleDateString("sv-SE", { timeZone: "Europe/Vienna" });
111	  const sauber = (x) => x.replace(/[\\/:*?"<>|]+/g, "_").replace(/\s+/g, " ").trim();
112	  return `${sauber(basis)} - vertraulich fuer ${sauber(wer)} ${tag}${endung}`.slice(0, 180);
113	}
114	
115	// ---------------------------------------------------------------- Umgehungsschutz
116	
117	const MUSTER = [
118	  /[A-Z0-9._%+-]{1,64}@[A-Z0-9.-]{1,120}\.[A-Z]{2,24}/gi, // E-Mail
119	  /\b(?:https?:\/\/|www\.)\S+/gi, // Links
120	  /(?:\+|00)\d[\d ()/.-]{6,20}\d/g, // internationale Rufnummer
121	  /\b0\d{2,5}(?:[ /.-]?\d){4,14}\b/g, // nationale Rufnummer
122	];
123	
124	/** Kontaktdaten aus Freitext entfernen. Liefert { text, bereinigt } */
125	export function anonymisieren(text) {
126	  let t = String(text ?? "");
127	  let bereinigt = false;
128	  for (const m of MUSTER) {
129	    t = t.replace(m, () => {
130	      bereinigt = true;
131	      return "[Kontaktangabe entfernt]";
132	    });
133	  }
134	  return { text: t, bereinigt };
135	}
136	
137	/** Pseudonym je Reihenfolge: 0 → „A“, 25 → „Z“, 26 → „AA“ */
138	export function pseudonymBuchstabe(i) {
139	  let n = Math.max(0, i | 0);
140	  let s = "";
141	  do {
142	    s = String.fromCharCode(65 + (n % 26)) + s;
143	    n = Math.floor(n / 26) - 1;
144	  } while (n >= 0);
145	  return s;
146	}
147	
148	// ---------------------------------------------------------------- Bieterverfahren
149	
150	export const RUNDEN_ARTEN = {
151	  indikativ: { label: "Indikative Angebote", kurz: "Indikativ", text: "Unverbindliche Preisindikation mit Bedingungen – Grundlage für die Auswahl der Shortlist." },
152	  verbindlich: { label: "Verbindliche Angebote", kurz: "Verbindlich", text: "Bindende Angebote der zugelassenen Bieter mit Finanzierungsnachweis und Zeitplan." },
153	};
154	
155	export const VERFAHREN_STATUS = {
156	  laufend: { label: "Runde läuft", ton: "ok" },
157	  auswertung: { label: "Auswertung", ton: "warn" },
158	  zuschlag: { label: "Zuschlag erteilt", ton: "ok" },
159	  abgeschlossen: { label: "Abgeschlossen", ton: "neutral" },
160	  abgebrochen: { label: "Abgebrochen", ton: "neutral" },
161	};
162	
163	export const GEBOT_STATUS = {
164	  abgegeben: { label: "Abgegeben", ton: "info" },
165	  zurueckgezogen: { label: "Zurückgezogen", ton: "neutral" },
166	  zuschlag: { label: "Zuschlag", ton: "ok" },
167	  unterlegen: { label: "Nicht berücksichtigt", ton: "neutral" },
168	};
169	
170	/** Pflichtangaben eines Gebots (Admin wählt je Verfahren; Preis ist immer Pflicht) */
171	export const GEBOT_PFLICHT = {
172	  bedingungen: "Bedingungen / Vorbehalte",
173	  finanzierung: "Finanzierungsnachweis",
174	  zeitplan: "Zeitplan bis Signing/Closing",
175	};
176	
177	export const ERINNERUNG_STUNDEN = 48;
178	
179	/** Gesamtpreis eines Gebots (für Vergleich und Provision) */
180	export function gebotGesamt(g, mwp) {
181	  if (!g) return null;
182	  if (g.preisModus === "proKwp") return g.preisProKwp && mwp ? Math.round(g.preisProKwp * mwp * 1000) : null;
183	  return g.preis || null;
184	}
185	export function gebotProKwp(g, mwp) {
186	  if (!g) return null;
187	  if (g.preisModus === "proKwp") return g.preisProKwp || null;
188	  return g.preis && mwp ? Math.round(g.preis / (mwp * 1000)) : null;
189	}
190	
191	/** Restzeit bis zur Frist als Text („2 Tg. 4 Std.“) */
192	export function restzeit(frist, jetzt = Date.now()) {
193	  const ms = new Date(frist).getTime() - jetzt;
194	  if (!Number.isFinite(ms)) return "–";
195	  if (ms <= 0) return "abgelaufen";
196	  const min = Math.floor(ms / 60000);
197	  const t = Math.floor(min / 1440);
198	  const h = Math.floor((min % 1440) / 60);
199	  const m = min % 60;
200	  if (t > 0) return `${t} Tg. ${h} Std.`;
201	  if (h > 0) return `${h} Std. ${m} Min.`;
202	  return `${m} Min.`;
203	}
204	
205	// ---------------------------------------------------------------- Investor-Pipeline
206	
207	export const PIPELINE_SPALTEN = [
208	  { id: "beobachten", label: "Beobachten", text: "Gemerkt, noch keine NDA" },
209	  { id: "nda", label: "NDA", text: "NDA akzeptiert, Freigabe ausstehend" },
210	  { id: "datenraum", label: "Datenraum", text: "Datenraum frei – Prüfung läuft" },
211	  { id: "angebot", label: "Angebot", text: "LOI oder Gebot abgegeben" },
212	  { id: "verhandlung", label: "Verhandlung", text: "LOI angenommen bzw. Zuschlag – Exklusivität" },
213	  { id: "gewonnen", label: "Gewonnen", text: "Kauf abgeschlossen" },
214	  { id: "verloren", label: "Verloren", text: "Abgelehnt oder anderweitig verkauft" },
215	];
216	export const PIPELINE_SPALTEN_IDS = PIPELINE_SPALTEN.map((s) => s.id);
217	export const AKTIVE_SPALTEN = ["beobachten", "nda", "datenraum", "angebot", "verhandlung"];
218	
219	/** Spalte aus Interesse-Status und eigenen Geboten (ohne manuelle Einordnung) */
220	export function pipelineSpalte(interesse, { gebotAbgegeben = false, zuschlag = false } = {}) {
221	  const s = interesse?.status;
222	  if (s === "abgeschlossen") return "gewonnen";
223	  if (s === "abgelehnt") return "verloren";
224	  if (s === "loi_angenommen" || zuschlag) return "verhandlung";
225	  if (s === "loi_abgegeben" || gebotAbgegeben) return "angebot";
226	  if (s === "nda_freigegeben") return "datenraum";
227	  if (s === "nda_angefragt") return "nda";
228	  return "beobachten";
229	}
