1	// src/lib/plattform/backend/demo/dealroomRegeln.js
2	//
3	// Reine Regeln des Deal-Rooms auf der Demo-Datenbank, die auch demo.js braucht
4	// (Freigabestufen beim Dokument-Download, Aufrufverlauf). Ohne Import von demo.js,
5	// damit keine Zirkelbezüge entstehen.
6	
7	import { investorStufe } from "../../dealroom";
8	
9	const TZ = "Europe/Vienna";
10	export const tagHeute = (d = new Date()) => d.toLocaleDateString("sv-SE", { timeZone: TZ });
11	
12	/** Ist der Investor (Interesse) zur verbindlichen Runde eines aktiven Bieterverfahrens zugelassen? */
13	export function verbindlichZugelassen(db, interesse) {
14	  if (!interesse) return false;
15	  const liste = db.dealroom?.verfahren || [];
16	  return liste.some(
17	    (v) =>
18	      v.projektId === interesse.projektId &&
19	      !["abgebrochen"].includes(v.status) &&
20	      (v.runden || []).some((r) => r.art === "verbindlich" && (r.teilnehmer || []).includes(interesse.id))
21	  );
22	}
23	
24	/** Stufe (1|2) eines Datenraum-Dokuments – Standard 1 */
25	export function dokumentStufe(db, dokumentId) {
26	  return Number(db.dealroom?.dokMeta?.[dokumentId]?.stufe) === 2 ? 2 : 1;
27	}
28	
29	/** Darf der Investor (Interesse) dieses Datenraum-Dokument nach Freigabestufe öffnen? */
30	export function datenraumStufeOk(db, dokument, interesse) {
31	  const stufe = investorStufe(interesse, { verbindlichZugelassen: verbindlichZugelassen(db, interesse) });
32	  return stufe >= dokumentStufe(db, dokument?.id);
33	}
34	
35	/** Aufruf eines Exposés je Tag zählen (Anbieter-Cockpit „Aufrufe über Zeit“), 400 Tage vorhalten */
36	export function aufrufVerlaufZaehlen(db, projektId) {
37	  db.aufrufVerlauf = db.aufrufVerlauf || {};
38	  const v = (db.aufrufVerlauf[projektId] = db.aufrufVerlauf[projektId] || {});
39	  const tag = tagHeute();
40	  v[tag] = (v[tag] || 0) + 1;
41	  const tage = Object.keys(v).sort();
42	  if (tage.length > 400) for (const t of tage.slice(0, tage.length - 400)) delete v[t];
43	}
