1	// src/lib/plattform/backend/demo/dealroom.js
2	//
3	// Deal-Room im Demo-Backend: Q&A mit Moderation, strukturiertes Bieterverfahren (verdeckte Gebote,
4	// Runden, Fristen, Zuschlag), Datenraum 2.0 (Ordner, Versionen, Freigabestufen, Zugriffsprotokoll,
5	// Wasserzeichen-Dateiname), Investor-Pipeline (Kanban, private Notizen/Tags, mehrere Suchprofile,
6	// Kennzahlen), Anbieter-Cockpit (Trichter, Aufrufe über Zeit, offene Fragen, Bieterstand) und
7	// Kontaktfreigabe (Umgehungsschutz).
8	//
9	// Referenz für die Frappe-Methoden in plattform/api/{qa,bieter,dealroom}.py (docs/API.md, Abschnitt 7).
10	// Daten liegen unter db.dealroom (eigene Sammlung, beim ersten Zugriff mit Demo-Daten ergänzt) –
11	// die übrige Demo-Datenbank bleibt unberührt.
12	//
13	// Rechte: jede Operation prüft Rolle UND Eigentum selbst:
14	//   admin    – alles, sieht Klarnamen
15	//   anbieter – nur eigene Projekte; Investoren nur als Pseudonym (bis Kontaktfreigabe)
16	//   investor – nur Projekte mit freigegebenem Datenraum (DATENRAUM_STATUS); nie fremde Gebote,
17	//              nie fremde Fragen (außer freigegebene Antworten „für alle“), Anbieter anonym
18	
19	import { BOERSE_STATUS, DATENRAUM_STATUS, statusLabel } from "../../prozesse";
20	import { LAENDER, PROJEKT_TYPEN, SUCHPROFIL_SCHWELLE } from "../../konstanten";
21	import { PlattformFehler, konflikt, nichtGefunden, ungueltig, verboten } from "../../fehler";
22	import * as v from "../../validierung";
23	import { projektOeffentlich } from "../../oeffentlich";
24	import { darfLesen } from "../../rechte";
25	import { matching } from "../../matching";
26	import { PHASEN } from "@/lib/invest/markt";
27	import {
28	  AKTIVE_SPALTEN, DATENRAUM_ORDNER, DATENRAUM_ORDNER_IDS, ERINNERUNG_STUNDEN, FRAGE_STATUS, GEBOT_PFLICHT, NOTIZ_TAGS_MAX,
29	  PIPELINE_SPALTEN_IDS, QA_FRIST_TAGE, QA_KATEGORIEN, RUNDEN_ARTEN, SUCHPROFILE_MAX, anonymisieren, gebotGesamt, gebotProKwp,
30	  investorStufe, ordnerVorschlag, pipelineSpalte, pseudonymBuchstabe, qaOeffentlicherStatus, wasserzeichenName,
31	} from "../../dealroom";
32	import { intern } from "../demo";
33	import { aendern, lesen, uploadLesen } from "./speicher";
34	import { jetzt, neueId, vorTagen } from "./hilfen";
35	import { datenraumStufeOk, dokumentStufe, tagHeute, verbindlichZugelassen } from "./dealroomRegeln";
36	import { kycSperre } from "./kycRegeln"; // KYC/KYB: Gebot und Zuschlag nur verifiziert
37	import { bonitaetSperre } from "./diensteRegeln"; // Dienste: Gebot nur mit gültiger Bonitätsauskunft, wenn Pflicht
38	import { anbieterZuschlagPruefen } from "./anbieterRegeln"; // Anbieter: kein Zuschlag auf ein vom Verkäufer abgelehntes Gebot (409)
39	
40	const { nachricht, benachrichtigen, protokoll, systemWechsel, darfDokument, dokumentMeta, nutzerById, kurz, nameVon, aktiveAdmins } = intern;
41	
42	const istAdmin = (n) => !!n?.rollen?.includes("admin");
43	const hatRolle = (n, r) => istAdmin(n) || r.some((x) => n?.rollen?.includes(x));
44	const MAIL_DEAL = "Im Deal-Room eines Projekts gibt es Neuigkeiten. Details finden Sie im Portal.";
45	const dealLink = (projektId, tab = "") => `/portal/dealroom/${projektId}${tab ? `?tab=${tab}` : ""}`;
46	
47	function angemeldet(n) {
48	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
49	}
50	
51	// ================================================================ Datenbestand
52	
53	function leer() {
54	  return { v: 1, fragen: [], verfahren: [], gebote: [], dokMeta: {}, zugriffe: [], notizen: [], suchprofile: {}, freigaben: [] };
55	}
56	
57	/** Sammlung sicherstellen; beim ersten Mal Demo-Daten ergänzen (nur Demo-Projekte, alles fiktiv) */
58	function bereit(db) {
59	  if (db.dealroom?.v) return db.dealroom;
60	  db.dealroom = leer();
61	  try {
62	    demoErgaenzen(db);
63	  } catch (e) {
64	    console.warn("[plattform-demo] Deal-Room-Demodaten nicht ergänzt:", e?.message);
65	  }
66	  return db.dealroom;
67	}
68	
69	async function lesenBereit() {
70	  const db = await lesen();
71	  if (db.dealroom?.v) return db;
72	  await aendern((d) => void bereit(d));
73	  return lesen();
74	}
75	
76	const aendernBereit = (fn) =>
77	  aendern((db) => {
78	    bereit(db);
79	    return fn(db);
80	  });
81	
82	// ================================================================ Rollen & Anonymität
83	
84	function projektLaden(db, id) {
85	  const p = db.projekte.find((x) => x.id === v.kennung(id));
86	  if (!p) throw nichtGefunden("Projekt nicht gefunden.");
87	  return p;
88	}
89	
90	const interesseVon = (db, projektId, investorId) => db.interessen.find((i) => i.projektId === projektId && i.investorId === investorId) || null;
91	
92	/** Rolle im Deal-Room eines Projekts: admin | anbieter | investor – sonst 403/404 */
93	function rolleIm(db, n, p, { investorFehler = true } = {}) {
94	  angemeldet(n);
95	  if (istAdmin(n)) return { rolle: "admin", interesse: null };
96	  if (p.anbieterId === n.id) return { rolle: "anbieter", interesse: null };
97	  if (n.rollen?.includes("investor")) {
98	    const i = interesseVon(db, p.id, n.id);
99	    if (i && DATENRAUM_STATUS.includes(i.status)) return { rolle: "investor", interesse: i };
100	    if (!investorFehler) return { rolle: null, interesse: i };
101	    throw verboten("Der Deal-Room öffnet sich nach Freigabe Ihrer NDA.");
102	  }
103	  throw verboten();
104	}
105	
106	/** Pseudonyme je Projekt („Investor A“, „Investor B“ …) in der Reihenfolge der NDA-Anfragen – stabil */
107	function pseudonyme(db, projektId) {
108	  const liste = db.interessen
109	    .filter((i) => i.projektId === projektId && (i.nda || i.status !== "gemerkt"))
110	    .sort((a, b) => String(a.nda?.am || a.erstelltAm).localeCompare(String(b.nda?.am || b.erstelltAm)) || a.id.localeCompare(b.id));
111	  return new Map(liste.map((i, idx) => [i.id, `Investor ${pseudonymBuchstabe(idx)}`]));
112	}
