193	function frageAusgabe(db, f, rolle, n, pseudo) {
194	  const basis = {
195	    id: f.id,
196	    projektId: f.projektId,
197	    kategorie: f.kategorie,
198	    kategorieLabel: QA_KATEGORIEN[f.kategorie] || f.kategorie,
199	    text: f.text,
200	    erstelltAm: f.erstelltAm,
201	    antwort: f.status === "veroeffentlicht" || rolle !== "investor" ? f.antwort || "" : "",
202	    antwortAm: f.status === "veroeffentlicht" || rolle !== "investor" ? f.antwortAm || null : null,
203	    oeffentlich: !!f.oeffentlich,
204	  };
205	  if (rolle === "investor") {
206	    const eigen = f.investorId === n.id;
207	    return {
208	      ...basis,
209	      eigen,
210	      status: qaOeffentlicherStatus(f.status),
211	      statusIntern: eigen ? f.status : undefined,
212	      von: eigen ? "Sie" : "Anderer Interessent",
213	      antwortVon: "Anbieter (über ÖkoInvest)",
214	      ablehnGrund: eigen && f.status === "abgelehnt" ? f.ablehnGrund : undefined,
215	    };
216	  }
217	  const ueberfaellig = f.status === "freigegeben" && f.fristAm && new Date(f.fristAm) < new Date();
218	  const out = { ...basis, status: f.status, statusLabel: FRAGE_STATUS[f.status]?.label || f.status, fristAm: f.fristAm || null, ueberfaellig, rueckfrage: f.rueckfrage || "", von: investorAnzeige(db, rolle, f.projektId, f.interesseId, pseudo) };
219	  if (rolle === "admin") {
220	    out.textOriginal = f.textOriginal || "";
221	    out.bereinigt = !!f.bereinigt;
222	    out.antwortOriginal = f.antwortOriginal || "";
223	    out.oeffentlichVorschlag = !!f.oeffentlichVorschlag;
224	    out.ablehnGrund = f.ablehnGrund || "";
225	    out.verlauf = f.verlauf || [];
226	  }
227	  return out;
228	}
