230	/** Fragen zu einem Projekt – je Rolle gefiltert und anonymisiert */
231	export async function qaListe(n, projektId) {
232	  const db = await lesenBereit();
233	  const p = projektLaden(db, projektId);
234	  const { rolle } = rolleIm(db, n, p);
235	  const pseudo = pseudonyme(db, p.id);
236	  let liste = db.dealroom.fragen.filter((f) => f.projektId === p.id);
237	  if (rolle === "anbieter") liste = liste.filter((f) => ["freigegeben", "beantwortet", "veroeffentlicht"].includes(f.status));
238	  if (rolle === "investor") liste = liste.filter((f) => f.investorId === n.id || (f.status === "veroeffentlicht" && f.oeffentlich));
239	  const reihenfolge = { eingereicht: 0, beantwortet: 1, freigegeben: 2, veroeffentlicht: 3, abgelehnt: 4 };
240	  liste.sort((a, b) => (reihenfolge[a.status] ?? 9) - (reihenfolge[b.status] ?? 9) || String(b.erstelltAm).localeCompare(String(a.erstelltAm)));
241	  const fragen = liste.map((f) => frageAusgabe(db, f, rolle, n, pseudo));
242	  return {
243	    rolle,
244	    fragen,
245	    zaehler: {
246	      gesamt: fragen.length,
247	      offen: fragen.filter((f) => (rolle === "investor" ? f.status === "offen" : ["eingereicht", "freigegeben", "beantwortet"].includes(f.status))).length,
248	      ueberfaellig: fragen.filter((f) => f.ueberfaellig).length,
249	      moderation: rolle === "admin" ? fragen.filter((f) => ["eingereicht", "beantwortet"].includes(f.status)).length : undefined,
250	    },
251	  };
252	}
