303	export async function qaAktion(n, id, daten = {}) {
304	  angemeldet(n);
305	  const aktion = v.auswahl(daten.aktion, ["antworten", "freigeben", "ablehnen", "antwortFreigeben", "zurueckgeben", "frist"], "");
306	  v.pflicht(aktion, "Unbekannte Aktion.");
307	  return aendernBereit((db) => {
308	    const f = db.dealroom.fragen.find((x) => x.id === v.kennung(id));
309	    if (!f) throw nichtGefunden("Frage nicht gefunden.");
310	    const p = projektLaden(db, f.projektId);
311	    const { rolle } = rolleIm(db, n, p, { investorFehler: true });
312	    const admin = rolle === "admin";
313	    if (aktion !== "antworten" && !admin) throw verboten("Nur für das Backoffice.");
314	    if (aktion === "antworten" && !["admin", "anbieter"].includes(rolle)) throw verboten("Antworten gibt der Anbieter des Projekts.");
315	    const investor = nutzerById(db, f.investorId);
316	    const anbieter = nutzerById(db, p.anbieterId);
317	    const schritt = (status, kommentar = "") => {
318	      f.status = status;
319	      f.verlauf = f.verlauf || [];
320	      f.verlauf.push({ status, am: jetzt(), vonId: n.id, kommentar: v.mehrzeilig(kommentar, 500) });
321	    };
322	    const fristTage = v.zahl(daten.fristTage, { min: QA_FRIST_TAGE.min, max: QA_FRIST_TAGE.max }) ?? QA_FRIST_TAGE.standard;
323	
324	    if (aktion === "freigeben") {
325	      if (f.status !== "eingereicht") throw konflikt("Die Frage wurde bereits moderiert.");
326	      if (daten.text !== undefined) {
327	        const t = v.mehrzeilig(daten.text, 3000);
328	        v.pflicht(t.length >= 10, "Der Fragetext ist zu kurz.");
329	        f.text = anonymisieren(t).text;
330	      }
331	      f.fristAm = heutePlusTage(fristTage);
332	      f.freigegebenAm = jetzt();
333	      schritt("freigegeben", `Anonymisiert an den Anbieter weitergegeben, Antwortfrist ${fristTage} Tage.`);
334	      benachrichtigen(db, anbieter, { art: "nachricht", titel: `Neue Frage eines Interessenten: ${p.titel}`, text: `${QA_KATEGORIEN[f.kategorie]} · Antwort bis ${new Date(f.fristAm).toLocaleDateString("de-DE", { timeZone: "Europe/Vienna" })}`, link: dealLink(p.id, "qa"), objektArt: "projekt", objektId: p.id }, { mailText: MAIL_DEAL });
335	    } else if (aktion === "ablehnen") {
336	      if (!["eingereicht", "freigegeben", "beantwortet"].includes(f.status)) throw konflikt("Die Frage ist bereits abgeschlossen.");
337	      const grund = v.mehrzeilig(daten.grund, 500);
338	      v.pflicht(grund.length >= 3, "Bitte geben Sie eine Begründung an.");
339	      f.ablehnGrund = grund;
340	      schritt("abgelehnt", grund);
341	      benachrichtigen(db, investor, { art: "nda", titel: `Frage nicht zugelassen: ${p.titel}`, text: grund, link: dealLink(p.id, "qa"), objektArt: "interesse", objektId: f.interesseId }, { mailText: MAIL_DEAL });
342	    } else if (aktion === "antworten") {
343	      if (!["freigegeben", "beantwortet"].includes(f.status)) throw konflikt(f.status === "eingereicht" ? "Die Frage ist noch in der Moderation." : "Die Frage ist bereits abgeschlossen.");
344	      const roh = v.mehrzeilig(daten.antwort, 5000);
345	      v.pflicht(roh.length >= 5, "Bitte geben Sie eine Antwort ein (mind. 5 Zeichen).");
346	      const a = anonymisieren(roh);
347	      f.antwort = a.text;
348	      f.antwortOriginal = a.bereinigt ? roh : "";
349	      f.antwortAm = jetzt();
350	      f.antwortVon = n.id;
351	      f.oeffentlichVorschlag = v.wahr(daten.oeffentlich);
352	      f.rueckfrage = "";
353	      schritt("beantwortet", a.bereinigt ? "Kontaktangaben automatisch entfernt." : "");
354	      if (!admin) {
355	        for (const adm of aktiveAdmins(db)) {
356	          benachrichtigen(db, adm, { art: "nachricht", titel: `Antwort zur Freigabe: ${p.titel}`, text: `${QA_KATEGORIEN[f.kategorie]} · ${a.text.slice(0, 140)}`, link: dealLink(p.id, "qa"), objektArt: "projekt", objektId: p.id }, { mailText: MAIL_DEAL });
357	        }
