369	      benachrichtigen(db, investor, { art: "nda", titel: `Antwort auf Ihre Frage: ${p.titel}`, text: `${QA_KATEGORIEN[f.kategorie]} · beantwortet`, link: dealLink(p.id, "qa"), objektArt: "interesse", objektId: f.interesseId }, { mailText: MAIL_DEAL });
