441	  const status = verfahrenStatus(db, vf);
442	  const out = {
443	    id: vf.id,
444	    projektId: vf.projektId,
445	    status,
446	    pflicht: vf.pflicht,
447	    hinweis: vf.hinweis || "",
448	    erstelltAm: vf.erstelltAm,
449	    runde: { nr: r.nr, art: r.art, label: RUNDEN_ARTEN[r.art]?.label, start: r.start, frist: r.frist, offen: rundeOffen(r), beendetAm: r.beendetAm || null },
450	    runden: vf.runden.map((x) => ({ nr: x.nr, art: x.art, label: RUNDEN_ARTEN[x.art]?.label, start: x.start, frist: x.frist, beendetAm: x.beendetAm || null, teilnehmerAnzahl: rolle === "investor" ? undefined : x.teilnehmer.length })),
451	    anbieterFreigabe: !!vf.anbieterFreigabe,
452	    zuschlag: null,
453	  };
454	  const pseudo = pseudonyme(db, p.id);
455	  const gebote = db.dealroom.gebote.filter((g) => g.verfahrenId === vf.id && g.status !== "zurueckgezogen");
456	  if (rolle === "investor") {
457	    const i = interesseVon(db, p.id, n.id);
458	    out.zugelassen = !!i && r.teilnehmer.includes(i.id) && ["laufend"].includes(status);
459	    out.eigeneGebote = db.dealroom.gebote.filter((g) => g.verfahrenId === vf.id && g.investorId === n.id).sort((a, b) => b.am.localeCompare(a.am)).map((g) => gebotAusgabe(db, g, rolle, pseudo, p));
460	    out.zuschlagEigen = vf.zuschlag ? vf.zuschlag.interesseId === i?.id : null;
461	    return out;
462	  }
463	  if (vf.zuschlag) out.zuschlag = { am: vf.zuschlag.am, preisGesamt: vf.zuschlag.preisGesamt, von: investorAnzeige(db, rolle, p.id, vf.zuschlag.interesseId, pseudo), gebotId: rolle === "admin" ? vf.zuschlag.gebotId : undefined, interesseId: rolle === "admin" ? vf.zuschlag.interesseId : undefined };
464	  const zeigen = rolle === "admin" || vf.anbieterFreigabe;
465	  out.matrix = zeigen
466	    ? gebote
467	        .map((g) => gebotAusgabe(db, g, rolle, pseudo, p))
468	        .sort((a, b) => b.runde - a.runde || (b.preisGesamt || 0) - (a.preisGesamt || 0))
469	    : null;
470	  out.geboteAnzahl = rolle === "admin" || vf.anbieterFreigabe ? gebote.filter((g) => g.runde === r.nr).length : undefined;
471	  if (rolle === "admin") {
472	    out.teilnehmer = r.teilnehmer.map((iid) => {
473	      const g = gebote.find((x) => x.interesseId === iid && x.runde === r.nr);
474	      return { ...investorAnzeige(db, "admin", p.id, iid, pseudo), interesseId: iid, geboten: !!g, gebotAm: g?.am || null };
475	    });
476	    out.erinnertAm = r.erinnertAm || null;
477	    out.verlauf = vf.verlauf || [];
478	  }
479	  return out;
480	}
