482	function erinnern(db, vf, p, { sofort = false } = {}) {
483	  const r = aktuelleRunde(vf);
484	  if (!rundeOffen(r)) return 0;
485	  const bis = new Date(r.frist).getTime() - Date.now();
486	  if (!sofort && (r.erinnertAm || bis > ERINNERUNG_STUNDEN * 3600e3)) return 0;
487	  let anzahl = 0;
488	  for (const iid of r.teilnehmer) {
489	    const hat = db.dealroom.gebote.some((g) => g.verfahrenId === vf.id && g.runde === r.nr && g.interesseId === iid && g.status === "abgegeben");
490	    if (hat) continue;
491	    const i = db.interessen.find((x) => x.id === iid);
492	    if (!i) continue;
493	    benachrichtigen(db, nutzerById(db, i.investorId), { art: "nda", titel: `Erinnerung Angebotsfrist: ${p.titel}`, text: `${RUNDEN_ARTEN[r.art].label} bis ${new Date(r.frist).toLocaleString("de-DE", { timeZone: "Europe/Vienna", dateStyle: "short", timeStyle: "short" })}`, link: dealLink(p.id, "bieter"), objektArt: "interesse", objektId: i.id }, { mailText: "Eine Angebotsfrist im Deal-Room eines Projekts läuft bald ab. Details finden Sie im Portal." });
494	    anzahl++;
495	  }
496	  r.erinnertAm = jetzt();
497	  return anzahl;
498	}
