577	  const aktion = v.auswahl(daten.aktion, ["frist", "beenden", "naechsteRunde", "anbieterFreigabe", "erinnern", "zuschlag", "abbrechen"], "");
578	  v.pflicht(aktion, "Unbekannte Aktion.");
579	  return aendernBereit((db) => {
580	    const vf = db.dealroom.verfahren.find((x) => x.id === v.kennung(id));
581	    if (!vf) throw nichtGefunden("Bieterverfahren nicht gefunden.");
582	    const p = projektLaden(db, vf.projektId);
583	    const status = verfahrenStatus(db, vf);
584	    const r = aktuelleRunde(vf);
585	    const log = (text) => vf.verlauf.push({ am: jetzt(), vonId: n.id, text });
586	    const ende = ["zuschlag", "abgeschlossen", "abgebrochen"].includes(status);
587	    let hinweis = "";
588	
589	    if (aktion === "frist") {
590	      if (ende) throw konflikt("Das Verfahren ist beendet.");
