592	      r.beendetAm = null;
593	      r.erinnertAm = null;
594	      vf.status = "laufend";
595	      log(`Frist Runde ${r.nr} geändert`);
596	      for (const iid of r.teilnehmer) {
597	        const i = db.interessen.find((x) => x.id === iid);
598	        if (i) benachrichtigen(db, nutzerById(db, i.investorId), { art: "nda", titel: `Neue Angebotsfrist: ${p.titel}`, text: `${RUNDEN_ARTEN[r.art].label} bis ${new Date(r.frist).toLocaleString("de-DE", { timeZone: "Europe/Vienna", dateStyle: "short", timeStyle: "short" })}`, link: dealLink(p.id, "bieter"), objektArt: "interesse", objektId: i.id }, { mailText: MAIL_DEAL });
599	      }
600	    } else if (aktion === "beenden") {
601	      if (!rundeOffen(r) || ende) throw konflikt("Die Runde ist bereits beendet.");
602	      r.beendetAm = jetzt();
603	      log(`Runde ${r.nr} vorzeitig beendet`);
604	    } else if (aktion === "naechsteRunde") {
605	      if (ende) throw konflikt("Das Verfahren ist beendet.");
606	      if (rundeOffen(r)) throw konflikt("Die laufende Runde ist noch offen – bitte zuerst beenden oder Frist abwarten.");
607	      const frist = fristPruefen(daten.frist);
608	      const art = v.auswahl(daten.art, RUNDEN_ARTEN, "verbindlich");
609	      const erlaubt = new Set(db.interessen.filter((i) => i.projektId === p.id && DATENRAUM_STATUS.includes(i.status) && i.status !== "abgeschlossen").map((i) => i.id));
610	      const teilnehmer = (Array.isArray(daten.teilnehmer) ? daten.teilnehmer : []).map(v.kennung).filter((x) => x && erlaubt.has(x));
611	      v.pflicht(teilnehmer.length >= 1, "Bitte wählen Sie mindestens einen Bieter für die nächste Runde (Shortlist).");
612	      if (!r.beendetAm) r.beendetAm = r.frist;
