614	      vf.status = "laufend";
615	      log(`Runde ${r.nr + 1} gestartet: ${RUNDEN_ARTEN[art].label}, Shortlist ${teilnehmer.length}`);
616	      for (const iid of erlaubt) {
617	        const i = db.interessen.find((x) => x.id === iid);
