627	          objektId: i.id,
628	        }, { mailText: MAIL_DEAL });
629	      }
630	    } else if (aktion === "anbieterFreigabe") {
631	      vf.anbieterFreigabe = v.wahr(daten.an);
632	      log(vf.anbieterFreigabe ? "Bieterstand für den Anbieter freigegeben (anonymisiert)" : "Bieterstand für den Anbieter gesperrt");
