657	      if (p.status === "veroeffentlicht") systemWechsel(db, "projekt", p, "reserviert", "Zuschlag im Bieterverfahren erteilt.");
658	      for (const x of db.dealroom.gebote.filter((y) => y.verfahrenId === vf.id && y.status === "unterlegen")) {
