689	export async function gebotAbgeben(n, daten = {}) {
690	  angemeldet(n);
691	  if (!hatRolle(n, ["investor"]) || istAdmin(n)) throw verboten("Gebote geben Investoren ab.");
692	  return aendernBereit((db) => {
693	    const vf = db.dealroom.verfahren.find((x) => x.id === v.kennung(daten.verfahrenId));
694	    if (!vf) throw nichtGefunden("Bieterverfahren nicht gefunden.");
695	    const p = projektLaden(db, vf.projektId);
696	    const { rolle, interesse } = rolleIm(db, n, p);
697	    if (rolle !== "investor") throw verboten();
698	    const r = aktuelleRunde(vf);
699	    const status = verfahrenStatus(db, vf);
700	    if (!r.teilnehmer.includes(interesse.id)) throw verboten("Sie sind für diese Runde nicht zugelassen.");
701	    kycSperre(db, "gebot", { kontoId: interesse.investorId, organisationId: interesse.organisationId || null }); // KYC/KYB
702	    bonitaetSperre(db, "gebot", { kontoId: interesse.investorId, organisationId: interesse.organisationId || null }); // Dienste: Bonität vor Gebot
703	    if (status !== "laufend" || !rundeOffen(r)) throw konflikt("Die Angebotsfrist ist abgelaufen – Gebote sind nicht mehr möglich.");
704	    const preisModus = v.auswahl(daten.preisModus, ["gesamt", "proKwp"], "gesamt");
