763	export async function datenraum(n, projektId, { besuch = false, ip = "" } = {}) {
764	  let db = await lesenBereit();
765	  const p = projektLaden(db, projektId);
766	  const { rolle, interesse } = rolleIm(db, n, p);
767	  if (rolle === "investor" && besuch) {
768	    const letzte = db.dealroom.zugriffe.findLast?.((z) => z.projektId === p.id && z.nutzerId === n.id && z.art === "datenraum");
769	    if (!letzte || Date.now() - new Date(letzte.am).getTime() > 30 * 60e3) {
770	      await aendernBereit((d) => zugriffLoggen(d, { projektId: p.id, nutzerId: n.id, interesseId: interesse.id, art: "datenraum", ip }));
771	      db = await lesen();
772	    }
773	  }
774	  const stufe = rolle === "investor" ? investorStufe(interesse, { verbindlichZugelassen: verbindlichZugelassen(db, interesse) }) : 2;
775	  let doks = db.dokumente.filter((d) => d.bezugArt === "projekt" && d.bezugId === p.id);
776	  if (rolle === "investor") doks = doks.filter((d) => d.kategorie === "datenraum");
777	  const metas = new Map(doks.map((d) => [d.id, metaVon(db, d)]));
778	  const nachfolger = new Map();
779	  for (const d of doks) {
780	    const vv = metas.get(d.id).versionVon;
781	    if (vv && metas.has(vv)) nachfolger.set(vv, d.id);
782	  }
783	  const aktuelle = doks.filter((d) => !nachfolger.has(d.id));
784	  const byId = new Map(doks.map((d) => [d.id, d]));
785	  const eintraege = aktuelle.map((d) => {
786	    const kette = [];
787	    let x = d;
788	    const gesehen = new Set();
789	    while (x && !gesehen.has(x.id)) {
790	      gesehen.add(x.id);
791	      kette.push(x);
792	      const vv = metas.get(x.id).versionVon;
793	      x = vv ? byId.get(vv) : null;
794	    }
795	    const m = metas.get(d.id);
796	    const gesperrt = rolle === "investor" && m.stufe > stufe;
797	    const version = kette.length;
798	    return {
799	      id: d.id,
800	      name: d.name,
801	      mime: d.mime,
802	      groesse: d.groesse,
803	      am: d.am,
804	      kategorie: d.kategorie,
805	      checkliste: d.checkliste || "",
806	      ordner: m.ordner,
807	      stufe: m.stufe,
808	      version,
809	      gesperrt,
810	      versionen: kette.slice(1).map((k, idx) => ({ id: k.id, name: k.name, am: k.am, groesse: k.groesse, version: version - idx - 1, gesperrt: rolle === "investor" && metas.get(k.id).stufe > stufe })),
811	      eigenerUpload: d.hochgeladenVon === n.id,
812	    };
813	  });
814	  const ordner = DATENRAUM_ORDNER.map((o) => ({ ...o, dokumente: eintraege.filter((e) => e.ordner === o.id).sort((a, b) => a.name.localeCompare(b.name, "de")) }));
815	  return { rolle, stufe, ordner, anzahl: eintraege.length, gesperrt: eintraege.filter((e) => e.gesperrt).length, projekt: { id: p.id, titel: p.titel } };
