937	/** Deal-Pipeline des Investors: alle Interessen als Kanban, Notizen, Kennzahlen, Suchprofile */
938	export async function pipeline(n) {
939	  angemeldet(n);
940	  if (!hatRolle(n, ["investor"])) throw verboten("Die Deal-Pipeline steht Investoren zur Verfügung.");
941	  const db = await lesenBereit();
942	  const notizen = new Map(db.dealroom.notizen.filter((x) => x.nutzerId === n.id).map((x) => [x.projektId, x]));
943	  const karten = [];
944	  for (const i of db.interessen.filter((x) => x.investorId === n.id)) {
945	    const p = db.projekte.find((x) => x.id === i.projektId);
946	    if (!p) continue;
947	    const eigene = db.dealroom.gebote.filter((g) => g.interesseId === i.id && g.status !== "zurueckgezogen");
948	    const zuschlag = eigene.some((g) => g.status === "zuschlag");
949	    const auto = pipelineSpalte(i, { gebotAbgegeben: eigene.length > 0, zuschlag });
950	    const notiz = notizen.get(p.id);
951	    const letztes = eigene.sort((a, b) => b.am.localeCompare(a.am))[0];
952	    if (!i.gemerkt && i.status === "gemerkt" && !notiz) continue;
953	    karten.push({
954	      interesseId: i.id,
955	      status: i.status,
956	      statusLabel: statusLabel("interesse", i.status),
957	      spalteAuto: auto,
958	      spalte: notiz?.spalte && PIPELINE_SPALTEN_IDS.includes(notiz.spalte) ? notiz.spalte : auto,
959	      manuell: !!(notiz?.spalte && notiz.spalte !== auto),
960	      projekt: projektOeffentlich(p),
961	      projektStatus: p.status,
962	      notiz: notiz ? { text: notiz.text, tags: notiz.tags || [], geaendertAm: notiz.geaendertAm } : null,
963	      gebote: eigene.length,
964	      letztesGebot: letztes ? { preisGesamt: gebotGesamt(letztes, p.mwp), runde: letztes.runde, status: letztes.status, am: letztes.am } : null,
965	      dealroom: DATENRAUM_STATUS.includes(i.status),
966	      geaendertAm: [i.geaendertAm, notiz?.geaendertAm].filter(Boolean).sort().pop(),
967	    });
968	  }
969	  karten.sort((a, b) => String(b.geaendertAm).localeCompare(String(a.geaendertAm)));
970	  const aktiv = karten.filter((k) => AKTIVE_SPALTEN.includes(k.spalteAuto));
971	  const mitPreis = aktiv.filter((k) => k.projekt.preisModus !== "anfrage" && (k.projekt.preisProKwp || k.projekt.preis) && k.projekt.mwp);
972	  const kwpSumme = mitPreis.reduce((s, k) => s + k.projekt.mwp * 1000, 0);
973	  const preisSumme = mitPreis.reduce((s, k) => s + (k.projekt.preisModus === "proKwp" ? k.projekt.preisProKwp * k.projekt.mwp * 1000 : k.projekt.preis), 0);
974	  const verteilung = (feld) => {
975	    const o = {};
976	    for (const k of aktiv) {
977	      const key = k.projekt[feld] || "–";
978	      o[key] = o[key] || { anzahl: 0, mwp: 0 };
979	      o[key].anzahl++;
980	      o[key].mwp = Math.round((o[key].mwp + (k.projekt.mwp || 0)) * 10) / 10;
981	    }
982	    return o;
983	  };
984	  const sichtbar = db.projekte.filter((p) => BOERSE_STATUS.includes(p.status));
985	  const profile = (db.dealroom.suchprofile[n.id] || []).map((sp) => {
986	    const treffer = sichtbar.map((p) => ({ p, m: matching(p, sp) })).filter((x) => x.m.score >= (sp.schwelle || SUCHPROFIL_SCHWELLE.standard)).sort((a, b) => b.m.score - a.m.score);
987	    return { ...sp, treffer: treffer.length, beste: treffer.slice(0, 3).map((x) => ({ id: x.p.id, titel: x.p.titel, score: x.m.score })) };
988	  });
989	  const tags = [...new Set(karten.flatMap((k) => k.notiz?.tags || []))].sort((a, b) => a.localeCompare(b, "de"));
990	  return {
991	    karten,
992	    tags,
993	    suchprofile: profile,
994	    kennzahlen: {
995	      aktiv: aktiv.length,
996	      mwpPipeline: Math.round(aktiv.reduce((s, k) => s + (k.projekt.mwp || 0), 0) * 10) / 10,
997	      preisProKwpMittel: kwpSumme ? Math.round(preisSumme / kwpSumme) : null,
998	      preisBasis: mitPreis.length,
999	      gewonnen: karten.filter((k) => k.spalteAuto === "gewonnen").length,
1000	      mwpGewonnen: Math.round(karten.filter((k) => k.spalteAuto === "gewonnen").reduce((s, k) => s + (k.projekt.mwp || 0), 0) * 10) / 10,
1001	      verloren: karten.filter((k) => k.spalteAuto === "verloren").length,
1002	      laender: verteilung("land"),
1003	      phasen: verteilung("phase"),
1004	      typen: verteilung("typ"),
1005	    },
1006	  };
