126	export function closingPruefen(c, kyc = {}) {
127	  const gruende = [];
128	  if (c.status !== "signing") gruende.push(c.status === "vorbereitung" ? "Zuerst Signing bestätigen." : "Closing ist in diesem Status nicht möglich.");
