131	  const offen = (c.cps || []).filter((x) => !["erfuellt", "verzichtet"].includes(x.status));
132	  if (offen.length) gruende.push(`${offen.length} Closing Condition(s) offen: ${offen.slice(0, 3).map((x) => x.label).join("; ")}${offen.length > 3 ? " …" : ""}.`);
