146	/** Meilensteine bereinigen (Summe ≤ Kaufpreis) */
147	export function meilensteineBereinigen(liste, kaufpreis) {
148	  const out = (Array.isArray(liste) ? liste : []).slice(0, 8).map((m) => ({
149	    label: String(m?.label || "").trim().slice(0, 120),
150	    betrag: Math.max(0, Math.round(Number(m?.betrag) || 0)),
151	    bedingung: String(m?.bedingung || "").trim().slice(0, 200),
152	    faelligAm: /^20\d\d-\d\d-\d\d$/.test(String(m?.faelligAm || "")) ? m.faelligAm : "",
153	    bezahltAm: /^20\d\d-\d\d-\d\d$/.test(String(m?.bezahltAm || "")) ? m.bezahltAm : "",
154	  })).filter((m) => m.label && m.betrag > 0);
155	  const summe = out.reduce((s, m) => s + m.betrag, 0);
156	  if (kaufpreis > 0 && summe > kaufpreis) {
157	    const e = new Error("Die Summe der Meilensteinzahlungen übersteigt den Kaufpreis.");
158	    e.status = 422;
159	    throw e;
160	  }
161	  return out;
162	}
