740	    const c = closingLaden(db, id);
741	    const p = db.projekte.find((x) => x.id === c.projektId);
742	    if (aktion === "uebergabe") {
743	      if (c.status !== "vollzogen") throw konflikt("Die Übergabe folgt nach dem Closing.");
744	      const u = c.uebergabe.find((x) => x.schluessel === daten.schluessel);
745	      if (!u) throw ungueltig("Unbekannter Punkt.");
