751	    } else {
752	      if (!CL_OFFEN.includes(c.status)) throw konflikt("Der Closing-Raum ist abgeschlossen.");
753	      if (aktion === "signing_punkt") {
754	        const def = SIGNING_PUNKTE.find((x) => x.schluessel === daten.schluessel);
755	        if (!def) throw ungueltig("Unbekannter Punkt.");
756	        if (def.auto) throw konflikt("Dieser Punkt wird automatisch aus dem KYC-Modul gesetzt.");
757	        if (c.status !== "vorbereitung") throw konflikt("Das Signing ist bereits erfolgt.");
758	        const s = c.signing.punkte.find((x) => x.schluessel === def.schluessel);
