763	        verlauf(c, n, `Signing-Checkliste: ${def.label} ${s.erledigt ? "erledigt" : "offen"}.`);
764	      } else if (aktion === "signing") {
765	        const kyc = kycFuer(db, c);
766	        const pr = signingPruefen(c, kyc);
767	        if (!kyc.kontaktFrei) pr.gruende.push("Kontaktfreigabe (Deal-Room) fehlt – vor dem Signing müssen sich die Parteien namentlich kennen.");
768	        if (pr.gruende.length) throw new PlattformFehler(409, `Signing nicht möglich: ${pr.gruende.join(" ")}`, kyc.kycKaeufer && kyc.kycVerkaeufer ? "signing" : "kyc");
769	        c.status = "signing";
770	        c.signingAm = /^20\d\d-\d\d-\d\d$/.test(String(daten.datum || "")) && daten.datum <= heute() ? daten.datum : heute();
771	        oeffentlich(c, n, "Signing bestätigt – Kaufvertrag unterzeichnet. Jetzt folgen die Closing Conditions.");
772	        beteiligteMelden(db, c, { titel: `Signing bestätigt: ${p?.titel || ""}`, text: "Der Kaufvertrag ist unterzeichnet. Offene Bedingungen und Fristen sehen Sie im Closing-Raum." });
773	      } else if (aktion === "cp") {
774	        const x = c.cps.find((y) => y.schluessel === daten.schluessel);
775	        if (!x) throw ungueltig("Unbekannte Bedingung.");
776	        const st = v.auswahl(daten.status, Object.keys(CP_STATUS), "");
777	        if (!st) throw ungueltig("Unbekannter Status.");
778	        const nachweis = v.text(daten.nachweis ?? x.nachweis, 300);
779	        if (st === "erfuellt") v.pflicht(nachweis.length >= 3, "Bitte einen Nachweis angeben (z. B. Dokument, Datum, Aktenzeichen).");
780	        if (st === "verzichtet") v.pflicht(v.text(daten.nachweis, 300).length >= 5, "Bitte den Verzicht begründen (wer hat verzichtet, Datum).");
781	        x.status = st;
782	        x.nachweis = nachweis;
783	        x.erfuelltAm = ["erfuellt", "verzichtet"].includes(st) ? heute() : "";
784	        x.vonId = n.id;
785	        if (daten.frist && /^20\d\d-\d\d-\d\d$/.test(daten.frist)) x.frist = daten.frist;
786	        oeffentlich(c, n, `Bedingung „${x.label}“: ${CP_STATUS[st].label}.`);
787	      } else if (aktion === "cp_neu") {
788	        const label = v.text(daten.label, 160);
789	        v.pflicht(label.length >= 5, "Bitte die Bedingung beschreiben (mind. 5 Zeichen).");
790	        const ver = v.auswahl(daten.verantwortlich, Object.keys(CL_VERANTWORTLICH), "oekoinvest");
791	        c.cps.push({ schluessel: `eigen_${c.cps.length + 1}`, reihenfolge: c.cps.length + 1, label, text: v.text(daten.text, 300), verantwortlich: ver, frist: /^20\d\d-\d\d-\d\d$/.test(String(daten.frist || "")) ? daten.frist : "", status: "offen", nachweis: "", erfuelltAm: "", vonId: n.id, gemeldetVonId: null });
792	        oeffentlich(c, n, `Neue Bedingung: ${label}.`);
793	      } else if (aktion === "zahlung_eingang") {
794	        if (c.status !== "signing") throw konflikt("Der Kaufpreis wird nach dem Signing gezahlt.");
795	        const datum = /^20\d\d-\d\d-\d\d$/.test(String(daten.datum || "")) ? daten.datum : heute();
796	        if (datum > heute()) throw ungueltig("Das Eingangsdatum darf nicht in der Zukunft liegen.");
797	        const betrag = v.zahl(daten.betrag, { min: 1, max: 1e11 }) ?? c.kaufpreis;
798	        const faelligJetzt = (c.meilensteine || []).length ? c.kaufpreis - c.meilensteine.filter((m) => !m.bezahltAm).reduce((s, m) => s + m.betrag, 0) : c.kaufpreis;
799	        if (betrag + 1 < Math.max(0, faelligJetzt)) throw ungueltig(`Eingegangen sind ${Math.round(betrag).toLocaleString("de-DE")} € – zum Closing fällig sind ${Math.round(faelligJetzt).toLocaleString("de-DE")} €.`);
800	        c.zahlung = { ...c.zahlung, eingangAm: datum, betrag: Math.round(betrag), bestaetigtVonId: n.id };
801	        oeffentlich(c, n, `Zahlungseingang bestätigt${c.zahlung.treuhand ? " (Treuhand-/Notaranderkonto)" : ""}.`);
802	      } else if (aktion === "abbrechen") {
