816	/** Closing vollziehen: Prüfung → Projekt „verkauft“ (Provision) → Provisionsrechnung (Finanzen) → Status vollzogen */
817	async function closingVollziehen(n, id, { ip = "" } = {}) {
818	  let db = await lesenBereit();
819	  const c0 = closingLaden(db, id);
820	  const kyc0 = kycFuer(db, c0);
821	  const pr = closingPruefen(c0, kyc0);
822	  if (!pr.ok) throw new PlattformFehler(409, `Closing nicht möglich: ${pr.gruende.join(" ")}`, kyc0.kycKaeufer && kyc0.kycVerkaeufer ? "closing" : "kyc");
823	  const p0 = db.projekte.find((x) => x.id === c0.projektId);
824	  // 1. Projekt → verkauft (Automat im Kern-Backend legt die Provision an)
825	  if (p0 && p0.status !== "verkauft") await statusWechsel(n, { art: "projekt", id: p0.id, nach: "verkauft", als: "admin", extra: { interesseId: c0.interesseId, kaufpreis: c0.kaufpreis }, ip });
826	  // 2. Provisionsrechnung über das Finanzen-Modul (Lauf „provision“)
827	  let rechnungFehler = "";
828	  try {
829	    const fin = await import("./finanzen");
830	    const kern = await import("./finanzen-kern");
831	    await fin.abrechnungslauf(kern.SYSTEM_FINANZEN, { art: "provision" });
832	  } catch (e) {
833	    rechnungFehler = e?.message || "unbekannt";
834	    console.warn("[plattform-demo] Provisionsrechnung beim Closing nicht erzeugt:", rechnungFehler);
835	  }
836	  // 3. Closing abschließen
837	  return aendern((d) => {
838	    const c = closingLaden(d, id);
839	    if (c.status === "vollzogen") return closingAusgabe(d, n, c, { detail: true });
840	    const pv = d.provisionen.filter((x) => x.projektId === c.projektId && x.interesseId === c.interesseId).sort((a, b) => String(b.erstelltAm).localeCompare(String(a.erstelltAm)))[0];
841	    c.provisionId = pv?.id || null;
842	    const vk = pv ? null : anbieterVorkenntnisAnerkannt(d, c.projektId, c.interesseId);
843	    if (vk) c.provisionEntfallen = { grund: "Vorkenntnis anerkannt", vorkenntnisId: vk.id };
844	    c.status = "vollzogen";
845	    c.vollzogenAm = heute();
846	    const beleg = pv ? (d.finanzen?.belege || []).find((b) => b.schluessel === `PV:${pv.id}` && b.status !== "storniert") : null;
847	    oeffentlich(c, n, "Closing vollzogen – Kaufgegenstand übergeht auf den Käufer. Übergabe-Checkliste ist offen.");
848	    verlauf(c, n, pv ? `Provision ${pv.id} (${pv.betrag} €) angelegt${beleg ? `, Provisionsrechnung ${beleg.nummer}` : rechnungFehler ? ` – Rechnung beim nächsten Lauf (${rechnungFehler})` : " – Rechnung folgt im nächsten Abrechnungslauf"}.` : vk ? "Keine Provision: Vorkenntnis anerkannt (§ 4 Abs. 2 der Besonderen Bedingungen) – keine Provisionsrechnung." : "Keine Provision gefunden (Projekt bereits vorher verkauft?).");
849	    c.geaendertAm = jetzt();
850	    const p = d.projekte.find((x) => x.id === c.projektId);
851	    beteiligteMelden(d, c, { titel: `Closing vollzogen: ${p?.titel || ""}`, text: "Der Deal ist abgeschlossen. Übergabe und Abschlussbericht finden Sie im Closing-Raum." });
852	    for (const a of aktiveAdmins(d).filter((x) => darfLesen(x, "provisionen")).slice(0, 5)) benachrichtigen(d, a, { art: "status", titel: `Closing vollzogen: ${p?.titel || ""}`, text: beleg ? `Provisionsrechnung ${beleg.nummer} erzeugt.` : vk ? "Keine Provision – Vorkenntnis anerkannt." : "Provisionsrechnung prüfen.", link: `/portal/admin/closing/${c.id}`, objektArt: "closing", objektId: c.id }, { mail: false });
853	    protokoll(d, n, "closing_vollzogen", "closing", c.id, `Closing ${c.id} vollzogen (${c.kaufpreis} €)`, ip);
854	    return closingAusgabe(d, n, c, { detail: true });
855	  });
856	}
