	if float(loi.get("preisProKwp") or 0) > 0 and float(mwp or 0) > 0:
		return {"betrag": _r(float(loi["preisProKwp"]) * float(mwp) * 1000), "quelle": "loi"}
	return {"betrag": 0, "quelle": ""}


def meilensteine_bereinigen(liste, kaufpreis):
