			"faelligAm": m.get("faelligAm") if _ist_datum(m.get("faelligAm")) else "", "bezahltAm": m.get("bezahltAm") if _ist_datum(m.get("bezahltAm")) else "",
		}
		if x["label"] and x["betrag"] > 0:
			out.append(x)
	if kaufpreis and sum(x["betrag"] for x in out) > kaufpreis:
