export async function clFristenLauf(n) {
  if (n) leseNoetig(n, "closing");
  const db = await lesenBereit();
  const faellig = [];
  for (const c of C(db).closings.filter((x) => CL_OFFEN.includes(x.status))) {
    const p = db.projekte.find((x) => x.id === c.projektId);
